jsLib:
/**
 * 就爱文学网（www.92xs.info）专用 jsLib —— 纯 ES5（Rhino 兼容）
 * 站点形态：杰奇 CMS 全 HTML 服务端渲染；目录单页全量；正文 div#ccontent 内 <br> 分段。
 * 约定：jsLib 只做纯计算，不发网络请求；baseUrl / java 一律当参数传入。
 */

/* ---------------- 基础 ---------------- */
function kbTrim(s) {
    return String(s === null || s === undefined ? '' : s).replace(/^[\s\u00a0\u3000]+|[\s\u00a0\u3000]+$/g, '');
}

function kbEsc(s) {
    return String(s === null || s === undefined ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function kbUnescape(s) {
    var t = String(s === null || s === undefined ? '' : s);
    t = t.replace(/&nbsp;/gi, ' ').replace(/&ensp;/gi, ' ').replace(/&emsp;/gi, '\u3000');
    t = t.replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"');
    t = t.replace(/&apos;/gi, "'").replace(/&#39;/g, "'").replace(/&amp;/gi, '&');
    t = t.replace(/&#x([0-9a-f]+);/gi, function (m, h) { return String.fromCharCode(parseInt(h, 16)); });
    t = t.replace(/&#(\d+);/g, function (m, d) { return String.fromCharCode(parseInt(d, 10)); });
    return t;
}

var X92_BASE = 'http://www.92xs.info';

function kbAbs(u) {
    var s = kbTrim(u);
    if (!s) return '';
    if (/^https?:\/\//i.test(s)) return s;
    if (s.indexOf('//') === 0) return 'http:' + s;
    return X92_BASE + (s.charAt(0) === '/' ? '' : '/') + s;
}

/* 封面：/files/article/image/{id/1000 取整}/{id}/{id}s.jpg —— 列表页无 <img>，按书籍 id 拼 */
function qsCover(u) {
    var s = String(u === null || u === undefined ? '' : u);
    /* 注意别用裸 (\d+)：域名里的 92 会先被命中 */
    var m = s.match(/\/book\/(\d+)\.html/) || s.match(/(\d+)[^\d]*$/);
    if (!m) return '';
    var id = m[1];
    var dir = Math.floor(parseInt(id, 10) / 1000);
    return X92_BASE + '/files/article/image/' + dir + '/' + id + '/' + id + 's.jpg';
}

/* 目录地址：详情页里 /html/{id}/ 是「免费阅读」入口；退化用 bookUrl 的 /book/{id}.html */
function qsTocUrl(html, url) {
    var h = String(html === null || html === undefined ? '' : html);
    var m = h.match(/\/html\/(\d+)\//);
    if (!m) m = String(url === null || url === undefined ? '' : url).match(/\/book\/(\d+)\.html/);
    if (!m) return '';
    return X92_BASE + '/html/' + m[1] + '/';
}

/* ---------------- 状态 / 分类 / 字数 ---------------- */
var KB_STATUS = {
    '连载中': '连载', '連載中': '连载', '连载': '连载', '連載': '连载',
    '已完成': '完结', '已完结': '完结', '完結': '完结', '完结': '完结', '全本': '完结',
    '断更': '断更', '斷更': '断更', '休刊': '休刊'
};

function kbStatus(v) {
    var s = kbTrim(v);
    if (!s) return '';
    if (KB_STATUS[s]) return KB_STATUS[s];
    if (s.indexOf('完') > -1) return '完结';
    if (s.indexOf('连载') > -1) return '连载';
    return s;
}

/* 详情页 #count 文本：分 类：玄幻小说 点 击：225531 字 数：19089580 状 态：连载中 */
function qsKind(t) {
    var s = String(t === null || t === undefined ? '' : t), out = [];
    /* 用「下一个字段名」做右边界，兼容 text() 有无空格两种拼接结果 */
    var c = s.match(/分\s*类[：:]\s*([\s\S]*?)(?=\s*(?:点\s*击|字\s*数|状\s*态|加入收藏|加入书架|$))/);
    var st = s.match(/状\s*态[：:]\s*([\s\S]*?)(?=\s*(?:加入收藏|加入书架|点击推荐|催更报错|$))/);
    if (c) { c = kbTrim(c[1]).replace(/[，,。.]$/, ''); if (c) out.push(c); }
    if (st) { var v = kbStatus(st[1]); if (v) out.push(v); }
    return out.join(',');
}

function qsWords(t) {
    var s = String(t === null || t === undefined ? '' : t);
    var m = s.match(/字\s*数[：:]\s*([\d,]+)/);
    return m ? kbWordsNum(m[1]) : '';
}

/* 搜索页字数形如 19089K；详情页是纯数字 */
function qsWordK(v) {
    var s = kbTrim(v).replace(/,/g, '');
    var m = s.match(/([\d.]+)\s*([KkMm万]?)/);
    if (!m) return '';
    var n = parseFloat(m[1]);
    if (!n) return '';
    var u = m[2];
    if (u === 'K' || u === 'k') n = n * 1000;
    else if (u === 'M' || u === 'm') n = n * 1000000;
    else if (u === '万') n = n * 10000;
    return kbWordsNum(Math.round(n));
}

function qsCat(v) {
    return kbTrim(String(v === null || v === undefined ? '' : v)).replace(/^[\[【(（]+|[\]】)）]+$/g, '');
}

function kbAuthors(s) {
    var t = kbTrim(s).replace(/^作\s*者[：:]\s*/, '');
    return t.replace(/[、，,;；\/]+/g, '/').replace(/\/{2,}/g, '/');
}

function kbWordsNum(w) {
    var n = parseInt(String(w === null || w === undefined ? '' : w).replace(/[^\d]/g, ''), 10);
    if (!n) return '';
    if (n >= 100000000) return (n / 100000000).toFixed(1) + '亿字';
    if (n >= 10000) return (n / 10000).toFixed(1) + '万字';
    return n + '字';
}

function kbDate(v) {
    if (v === null || v === undefined || v === '') return '';
    var s = String(v);
    var m = s.match(/(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})/);
    if (m) return m[1] + '-' + (m[2].length < 2 ? '0' + m[2] : m[2]) + '-' + (m[3].length < 2 ? '0' + m[3] : m[3]);
    /* 搜索页是 22-02-11 这种两位年份 */
    var m2 = s.match(/(\d{2})[-/](\d{1,2})[-/](\d{1,2})/);
    if (m2) {
        var y = parseInt(m2[1], 10);
        y = y > 70 ? 1900 + y : 2000 + y;
        return y + '-' + (m2[2].length < 2 ? '0' + m2[2] : m2[2]) + '-' + (m2[3].length < 2 ? '0' + m2[3] : m2[3]);
    }
    var n = parseInt(s, 10);
    if (!n || n <= 0) return '';
    if (n < 100000000000) n = n * 1000;
    var d = new Date(n);
    var mo = d.getMonth() + 1, da = d.getDate();
    return d.getFullYear() + '-' + (mo < 10 ? '0' + mo : mo) + '-' + (da < 10 ? '0' + da : da);
}

/* ---------------- 简介：切段 + 每段两个全角空格 ---------------- */
var KB_IND = '\u3000\u3000';

function kbIntro(html) {
    var t = String(html === null || html === undefined ? '' : html);
    t = t.replace(/<br\s*\/?>/gi, '\n');
    t = t.replace(/<\/(p|div|h[1-6]|li|tr)>/gi, '\n');
    t = t.replace(/<[^>]+>/g, '');
    t = kbUnescape(t);
    t = t.replace(/\r\n?/g, '\n');
    t = t.replace(/[.．。]{2,}\s*$/, '');          // 站方截断用的连续省略点
    t = t.replace(/^[\s\u3000]*小说介绍[\s\u3000]*/, '');
    /* 源站把原段落间的换行压成了 2 个以上空格，按空档还原分段 */
    t = t.replace(/[\s\u3000\u00a0]{2,}/g, '\n');
    var lines = t.split('\n'), out = [], i, l;
    for (i = 0; i < lines.length; i++) {
        l = kbTrim(lines[i]);
        if (!l || l.length < 2) continue;
        out.push(KB_IND + l);
    }
    return out.join('\n');
}

/* ---------------- 正文：去站点注入块 + <br> 分段 ---------------- */
var QS_AD = /92xs|最新网址|正在手打中|全文字更新|牢记网址|请记住本站|天才一秒记住|本章未完|点击下一页|txt下载|妙书屋|www\./i;

function qsContent(html) {
    var t = String(html === null || html === undefined ? '' : html);
    if (!t) return '<p>△ 正文获取失败</p>';
    var typing = /正在手打中|请重新刷新页面/.test(t);   // 站方还没录完的新章
    /* 站点在每个正文头尾注入的「最新网址」块 */
    t = t.replace(/<div[^>]*id=["']center_tip["'][^>]*>[\s\S]*?<\/div>/gi, '');
    t = t.replace(/<script[\s\S]*?<\/script>/gi, '');
    t = t.replace(/<style[\s\S]*?<\/style>/gi, '');
    t = t.replace(/<br\s*\/?>/gi, '\n');
    t = t.replace(/<\/(p|div|h[1-6]|li|tr|td)>/gi, '\n');
    t = t.replace(/<[^>]+>/g, '');
    t = kbUnescape(t);
    t = t.replace(/\r\n?/g, '\n');
    var lines = t.split('\n'), out = [], i, l;
    for (i = 0; i < lines.length; i++) {
        l = lines[i].replace(/^[\s\u3000\u00a0]+/, '').replace(/[\s\u3000\u00a0]+$/, '');
        if (!l || l.length < 2) continue;
        if (QS_AD.test(l)) continue;                                  // 网址/手打中/广告行
        if (/^《[^》]{1,30}》\s*第[^\n]{1,30}$/.test(l)) continue;      // 手打章里重复的书名+章节标题
        if (/^[.．,，\s]*(?:com|net|cc|org|cn)[.。．]/i.test(l)) continue;  // 纯域名残渣行
        out.push('<p>' + kbEsc(l) + '</p>');
    }
    if (!out.length) return '<p>△ 本章内容为空，可能为付费章节或需要登录</p>';
    if (typing) out.push('<p>△ 本章站点尚未录入完整（页面提示「正在手打中」），稍后刷新或换源重试</p>');
    return out.join('\n');
}

function kbTocName(s) {
    var t = kbTrim(s);
    t = t.replace(/[（(【\[]\s*(求|感谢|本章|PS|ps|未完)[^）)】\]]*[）)】\]]/g, '');
    t = t.replace(/^正文\s*/, '');
    t = t.replace(/\s+/g, ' ');
    return kbTrim(t);
}
